        try! rustCall { uniffi_livekit_telemetry_fn_free_telemetrytransport(handle, $0) }
    }

    /**
     * Send `request` once and return the collector's answer, whatever its status.
     */
    open func send(request: ExportRequest) async throws -> ExportResponse {
        try await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_livekit_telemetry_fn_method_telemetrytransport_send(
                    self.uniffiCloneHandle(),
                    FfiConverterTypeExportRequest_lower(request)
