            },
            pollFunc: ffi_livekit_telemetry_rust_future_poll_rust_buffer,
            completeFunc: ffi_livekit_telemetry_rust_future_complete_rust_buffer,
            freeFunc: ffi_livekit_telemetry_rust_future_free_rust_buffer,
            liftFunc: FfiConverterTypeExportResponse_lift,
            errorHandler: FfiConverterTypeExportError_lift
