/// Put the implementation in a struct so we don't pollute the top-level namespace
private enum UniffiCallbackInterfaceTelemetryTransport {
    /// Create the VTable using a series of closures.
    /// Swift automatically converts these into C callback functions.
    ///
    /// Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceTelemetryTransport = .init(
        uniffiFree: { (uniffiHandle: UInt64) in
            do {
                try FfiConverterTypeTelemetryTransport.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface TelemetryTransport: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTelemetryTransport.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface TelemetryTransport: handle missing in uniffiClone")
            }
        },
        send: { (
            uniffiHandle: UInt64,
            request: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> ExportResponse in
                guard let uniffiObj = try? FfiConverterTypeTelemetryTransport.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.send(
                    request: FfiConverterTypeExportRequest_lift(request)
                )
            }

            let uniffiHandleSuccess = { (returnValue: ExportResponse) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeExportResponse_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { statusCode, errorBuf in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeExportError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    /// Rust stores this pointer for future callback invocations, so it must live
    /// for the process lifetime (not just for the init function call).
    static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceTelemetryTransport> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceTelemetryTransport>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitTelemetryTransport() {
    uniffi_livekit_telemetry_fn_init_callback_vtable_telemetrytransport(UniffiCallbackInterfaceTelemetryTransport.vtablePtr)
}

