/**
 * Pipeline health as seen by the SDK: [`Telemetry::stats`](crate::Telemetry::stats).
 */
public struct TelemetryStats: Equatable, Hashable {
    /**
     * What the upload policy is doing right now.
     */
    public var status: TelemetryStatus
    /**
     * Records lost for any reason (sum of the `dropped_*` fields).
     */
    public var dropped: UInt64
    /**
     * Records evicted from the in-memory queue, spans dropped from a full span buffer, and
     * tracks a session did not wait on past 256 at once (a subscribe loses its span, a published
     * track its fast polling).
     */
    public var droppedQueueFull: UInt64
    /**
     * Records lost because no cache, not even memory, could take their batch.
     */
    public var droppedCacheError: UInt64
    /**
     * Records evicted from the cache by its size or file-count bound.
     */
    public var droppedCacheFull: UInt64
    /**
     * Records in cached batches past the 24 h age limit.
     */
    public var droppedExpired: UInt64
    /**
     * Records in cached batches that failed their integrity check.
     */
    public var droppedCorrupt: UInt64
    /**
     * Custom events and attributes refused at the door, over the limits.
     */
    public var droppedInvalid: UInt64
    /**
     * Records the collector rejected (a final 4xx/5xx, or a partial success).
     */
    public var droppedRejected: UInt64
    /**
     * Single records larger than the collector accepts.
     */
    public var droppedOversized: UInt64
    /**
     * Records evicted from the cache while the collector held uploads off.
     */
    public var droppedThrottled: UInt64
    /**
     * Records for a project that receives nothing (self-hosted, no grant, disabled, 404).
     */
    public var droppedDisabled: UInt64
    /**
     * Discrete events dropped by the flood guard.
     */
    public var droppedRateLimited: UInt64
    /**
     * Records deleted by the opt-out.
     */
    public var droppedPurged: UInt64
    /**
     * Batches the collector accepted.
     */
    public var uploadsSent: UInt64
    /**
     * Compressed bytes the collector accepted.
     */
    public var uploadBytes: UInt64
    /**
     * Upload attempts that failed transiently before the timeout (a network error, 429, 5xx).
     */
    public var uploadFailures: UInt64
    /**
     * Upload attempts that got no answer within `export_timeout_ms`; not counted as failures.
     */
    public var uploadTimeouts: UInt64
    /**
     * Tokens the collector refused (401/403).
     */
    public var uploadsUnauthorized: UInt64
    /**
     * Soft holds that reached the cap.
     */
    public var holdsCapped: UInt64
    /**
     * Batches the disk cache could not store, kept in memory instead.
     */
    public var cacheWriteErrors: UInt64
    /**
     * Batches currently waiting in the cache.
     */
    public var cachedBatches: UInt64

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(
        /*
         * What the upload policy is doing right now.
         */ status: TelemetryStatus,
        /*
            * Records lost for any reason (sum of the `dropped_*` fields).
            */ dropped: UInt64,
        /*
            * Records evicted from the in-memory queue, spans dropped from a full span buffer, and
            * tracks a session did not wait on past 256 at once (a subscribe loses its span, a published
            * track its fast polling).
            */ droppedQueueFull: UInt64,
        /*
            * Records lost because no cache, not even memory, could take their batch.
            */ droppedCacheError: UInt64,
        /*
            * Records evicted from the cache by its size or file-count bound.
            */ droppedCacheFull: UInt64,
        /*
            * Records in cached batches past the 24 h age limit.
            */ droppedExpired: UInt64,
        /*
            * Records in cached batches that failed their integrity check.
            */ droppedCorrupt: UInt64,
        /*
            * Custom events and attributes refused at the door, over the limits.
            */ droppedInvalid: UInt64,
        /*
            * Records the collector rejected (a final 4xx/5xx, or a partial success).
            */ droppedRejected: UInt64,
        /*
            * Single records larger than the collector accepts.
            */ droppedOversized: UInt64,
        /*
            * Records evicted from the cache while the collector held uploads off.
            */ droppedThrottled: UInt64,
        /*
            * Records for a project that receives nothing (self-hosted, no grant, disabled, 404).
            */ droppedDisabled: UInt64,
        /*
            * Discrete events dropped by the flood guard.
            */ droppedRateLimited: UInt64,
        /*
            * Records deleted by the opt-out.
            */ droppedPurged: UInt64,
        /*
            * Batches the collector accepted.
            */ uploadsSent: UInt64,
        /*
            * Compressed bytes the collector accepted.
            */ uploadBytes: UInt64,
        /*
            * Upload attempts that failed transiently before the timeout (a network error, 429, 5xx).
            */ uploadFailures: UInt64,
        /*
            * Upload attempts that got no answer within `export_timeout_ms`; not counted as failures.
            */ uploadTimeouts: UInt64,
        /*
            * Tokens the collector refused (401/403).
            */ uploadsUnauthorized: UInt64,
        /*
            * Soft holds that reached the cap.
            */ holdsCapped: UInt64,
        /*
            * Batches the disk cache could not store, kept in memory instead.
            */ cacheWriteErrors: UInt64,
        /*
            * Batches currently waiting in the cache.
            */ cachedBatches: UInt64
    ) {
        self.status = status
        self.dropped = dropped
        self.droppedQueueFull = droppedQueueFull
        self.droppedCacheError = droppedCacheError
        self.droppedCacheFull = droppedCacheFull
        self.droppedExpired = droppedExpired
        self.droppedCorrupt = droppedCorrupt
        self.droppedInvalid = droppedInvalid
        self.droppedRejected = droppedRejected
        self.droppedOversized = droppedOversized
        self.droppedThrottled = droppedThrottled
        self.droppedDisabled = droppedDisabled
        self.droppedRateLimited = droppedRateLimited
        self.droppedPurged = droppedPurged
        self.uploadsSent = uploadsSent
        self.uploadBytes = uploadBytes
        self.uploadFailures = uploadFailures
        self.uploadTimeouts = uploadTimeouts
        self.uploadsUnauthorized = uploadsUnauthorized
        self.holdsCapped = holdsCapped
        self.cacheWriteErrors = cacheWriteErrors
        self.cachedBatches = cachedBatches
    }
}

